def main():
    print(f"Translating {len(DOC_FILES)} markdown documentation files to Simplified Chinese...")
    for rel_path in DOC_FILES:
        build_localized_file(rel_path, "zh", TRANSLATIONS_ZH)

    # Verification
    docs_dir = os.path.join(REPO_ROOT, "docs")
    zh_dir = os.path.join(docs_dir, "zh")
    generated_files = []
    for root, dirs, files in os.walk(zh_dir):
        for file in files:
            if file.endswith(".md"):
                rel_path = os.path.relpath(os.path.join(root, file), zh_dir)
                generated_files.append(rel_path.replace("\\", "/"))

    generated_files.sort()
    print(f"Successfully generated {len(generated_files)} Simplified Chinese documentation files in docs/zh/.")
    if len(generated_files) == len(DOC_FILES):
        print("Verification passed: All 59 documentation files generated successfully.")
    else:
        print(f"Verification mismatch: Expected {len(DOC_FILES)} files, but found {len(generated_files)}.")

if __name__ == "__main__":
    main()
